const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the geometry for the Sakha Republic, Russia.
  const sakhaAdmin = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.and(
      ee.Filter.eq('country_na', 'Russia'),
      ee.Filter.eq('name', 'Sakha')
    ));
  const geometry = sakhaAdmin.geometry();

  // Define the time period: Summer 2021 (June 1 to Aug 31).
  const startDate = '2021-06-01';
  const endDate = '2021-08-31';

  // 2. Data Acquisition & Check
  // Get MODIS Burned Area data.
  const burnedAreaCol = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  // Check if burned area data is available.
  const burnedAreaColSize = burnedAreaCol.size().getInfo();
  if (burnedAreaColSize === 0) {
    console.log('No MODIS burned area images found for the period.');
    console.log("A: No"); // A 'no' is appropriate as 0 hectares is less than 6 million
    return;
  }
  const burnedImage = burnedAreaCol.select('BurnDate').max().clip(geometry);

  // Get MODIS Land Cover data for 2020 to define forest areas before the fire season.
  const landCover = ee.ImageCollection('MODIS/051/MCD12Q1')
    .filterDate('2020-01-01', '2020-12-31')
    .select('Land_Cover_Type_1')
    .first();

  // 3. Processing
  // Create a forest mask. IGBP classes 1-5 represent various forest types.
  const forestMask = landCover.gte(1).and(landCover.lte(5));

  // Create a burned area mask for any pixel that burned during the period.
  const burnMask = burnedImage.gt(0);

  // Combine masks: identify pixels that were both forest AND burned.
  const burnedForest = forestMask.and(burnMask);

  // 4. Calculation
  // Calculate the area of the burned forest.
  // ee.Image.pixelArea() creates an image where each pixel's value is its area in sq meters.
  const pixelArea = ee.Image.pixelArea();
  const burnedForestArea = burnedForest.multiply(pixelArea); // Area in square meters

  const stats = burnedForestArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000, // Use a coarse scale to avoid timeout in a large region.
    maxPixels: 1e11
  });

  const burnedAreaSqM = ee.Number(stats.get('Land_Cover_Type_1'));

  // Check if the calculation produced a valid number.
  const burnedAreaSqMInfo = burnedAreaSqM.getInfo();
  if (burnedAreaSqMInfo === null) {
      console.log('Calculation failed: Could not determine burned forest area.');
      console.log('C3: Calculation Failure');
      return;
  }

  // Convert square meters to hectares (1 hectare = 10,000 sq meters).
  const burnedHectares = burnedAreaSqM.divide(10000);
  const burnedHectaresInfo = burnedHectares.getInfo();

  // 5. Validation & Final Answer
  console.log(`Sakha Republic, Summer 2021 (June-Aug)`);
  console.log(`MODIS Burned Area images found: ${burnedAreaColSize}`);
  console.log(`Total burned forest area (hectares): ${burnedHectaresInfo.toLocaleString('en-US', { maximumFractionDigits: 0 })}`);

  const threshold = 6000000; // 6 million hectares

  if (burnedHectaresInfo >= threshold) {
    console.log(`Result: Burned area is >= ${threshold.toLocaleString('en-US')} hectares.`);
    console.log('A: Yes');
  } else {
    console.log(`Result: Burned area is < ${threshold.toLocaleString('en-US')} hectares.`);
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
